export const productVariantAttributeValues = pgTable("product_variant_attribute_values", {
	variantId: uuid("variant_id").notNull(),
	productId: uuid("product_id").notNull(),
	definitionId: uuid("definition_id").notNull(),
	valueId: uuid("value_id").notNull(),
}, (table) => [
	index("idx_pvav_product_id").using("btree", table.productId.asc().nullsLast().op("uuid_ops")),
	index("idx_pvav_value_id").using("btree", table.valueId.asc().nullsLast().op("uuid_ops")),
	foreignKey({
			columns: [table.productId, table.definitionId, table.valueId],
			foreignColumns: [productAttributeLinkValues.productId, productAttributeLinkValues.definitionId, productAttributeLinkValues.valueId],
			name: "product_variant_attribute_val_product_id_definition_id_val_fkey"
		}).onDelete("cascade"),
	foreignKey({
			columns: [table.productId, table.definitionId],
			foreignColumns: [productAttributeLinks.productId, productAttributeLinks.definitionId],
			name: "product_variant_attribute_values_product_id_definition_id_fkey"
		}).onDelete("cascade"),
	foreignKey({
			columns: [table.variantId, table.productId],
			foreignColumns: [productVariants.id, productVariants.productId],
			name: "product_variant_attribute_values_variant_id_product_id_fkey"
		}).onDelete("cascade"),
	primaryKey({ columns: [table.definitionId, table.variantId], name: "product_variant_attribute_values_pkey"}),
]);

export const productAttributeLinkValues = pgTable("product_attribute_link_values", {
	productId: uuid("product_id").notNull(),
	definitionId: uuid("definition_id").notNull(),
	valueId: uuid("value_id").notNull(),
	priceAdjustment: numeric("price_adjustment", { precision: 12, scale:  2 }),
	position: smallint().default(0).notNull(),
}, (table) => [
	index("idx_palv_value_id").using("btree", table.valueId.asc().nullsLast().op("uuid_ops")),
	foreignKey({
			columns: [table.definitionId],
			foreignColumns: [attributeDefinitions.id],
			name: "product_attribute_link_values_definition_id_fkey"
		}).onDelete("cascade"),
	foreignKey({
			columns: [table.productId],
			foreignColumns: [products.id],
			name: "product_attribute_link_values_product_id_fkey"
		}).onDelete("cascade"),
	foreignKey({
			columns: [table.valueId],
			foreignColumns: [attributeValues.id],
			name: "product_attribute_link_values_value_id_fkey"
		}).onDelete("restrict"),
	primaryKey({ columns: [table.definitionId, table.productId, table.valueId], name: "product_attribute_link_values_pkey"}),
	check("product_attribute_link_values_position_check", sql`"position" >= 0`),
	check("product_attribute_link_values_price_adjustment_check", sql`price_adjustment >= (0)::numeric`),
]);

export const productAttributeLinks = pgTable("product_attribute_links", {
	productId: uuid("product_id").notNull(),
	definitionId: uuid("definition_id").notNull(),
	isVariantAxis: boolean("is_variant_axis").default(false).notNull(),
	variantAxisPosition: smallint("variant_axis_position"),
	axisLabel: varchar("axis_label", { length: 50 }),
	displayPosition: smallint("display_position"),
}, (table) => [
	uniqueIndex("idx_pal_variant_axis_position").using("btree", table.productId.asc().nullsLast().op("int2_ops"), table.variantAxisPosition.asc().nullsLast().op("int2_ops")).where(sql`is_variant_axis`),
	foreignKey({
			columns: [table.definitionId],
			foreignColumns: [attributeDefinitions.id],
			name: "product_attribute_links_definition_id_fkey"
		}).onDelete("restrict"),
	foreignKey({
			columns: [table.productId],
			foreignColumns: [products.id],
			name: "product_attribute_links_product_id_fkey"
		}).onDelete("cascade"),
	primaryKey({ columns: [table.definitionId, table.productId], name: "product_attribute_links_pkey"}),
	check("product_attribute_links_check", sql`(NOT is_variant_axis) OR (variant_axis_position IS NOT NULL)`),
	check("product_attribute_links_display_position_check", sql`(display_position IS NULL) OR (display_position >= 0)`),
	check("product_attribute_links_variant_axis_position_check", sql`(variant_axis_position IS NULL) OR (variant_axis_position >= 0)`),
]);

export const householdMembers = pgTable("household_members", {
	householdId: uuid("household_id").notNull(),
	profileId: uuid("profile_id").notNull(),
	role: varchar({ length: 10 }).default('member').notNull(),
	joinedAt: timestamp("joined_at", { withTimezone: true, mode: 'string' }).defaultNow().notNull(),
	leftAt: timestamp("left_at", { withTimezone: true, mode: 'string' }),
	updatedAt: timestamp("updated_at", { withTimezone: true, mode: 'string' }).defaultNow().notNull(),
}, (table) => [
	index("idx_household_members_profile_id").using("btree", table.profileId.asc().nullsLast().op("uuid_ops")),
	uniqueIndex("one_active_household_per_profile").using("btree", table.profileId.asc().nullsLast().op("uuid_ops")).where(sql`(left_at IS NULL)`),
	foreignKey({
			columns: [table.householdId],
			foreignColumns: [households.id],
			name: "household_members_household_id_fkey"
		}).onDelete("cascade"),
	foreignKey({
			columns: [table.profileId],
			foreignColumns: [profiles.id],
			name: "household_members_profile_id_fkey"
		}).onDelete("cascade"),
	primaryKey({ columns: [table.householdId, table.profileId], name: "household_members_pkey"}),
	check("household_members_role_check", sql`(role)::text = ANY ((ARRAY['manager'::character varying, 'member'::character varying])::text[])`),
]);

